CREATE TYPE "SalesDocumentStatus" AS ENUM ('DRAFT','SENT','ACCEPTED','DECLINED','EXPIRED','CONVERTED','VOID');
ALTER TABLE "Invoice" ADD COLUMN "paidAmount" DECIMAL(19,4) NOT NULL DEFAULT 0, ADD COLUMN "creditedAmount" DECIMAL(19,4) NOT NULL DEFAULT 0;
CREATE TABLE "Quotation" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"customerId" UUID NOT NULL,"number" TEXT NOT NULL,"status" "SalesDocumentStatus" NOT NULL DEFAULT 'DRAFT',"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"issueDate" DATE NOT NULL,"expiryDate" DATE NOT NULL,"subtotal" DECIMAL(19,4) NOT NULL,"taxTotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"total" DECIMAL(19,4) NOT NULL,"items" JSONB NOT NULL,"notes" TEXT,"convertedInvoiceId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Quotation_pkey" PRIMARY KEY("id"));
CREATE TABLE "PaymentReceived" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"customerId" UUID NOT NULL,"invoiceId" UUID NOT NULL,"reference" TEXT NOT NULL,"amount" DECIMAL(19,4) NOT NULL,"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"paymentDate" DATE NOT NULL,"method" TEXT NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PaymentReceived_pkey" PRIMARY KEY("id"));
CREATE TABLE "CreditNote" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"customerId" UUID NOT NULL,"invoiceId" UUID NOT NULL,"number" TEXT NOT NULL,"amount" DECIMAL(19,4) NOT NULL,"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"issueDate" DATE NOT NULL,"reason" TEXT NOT NULL,"isVoid" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CreditNote_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "Quotation_organizationId_number_key" ON "Quotation"("organizationId","number"); CREATE INDEX "Quotation_organizationId_status_idx" ON "Quotation"("organizationId","status");
CREATE UNIQUE INDEX "PaymentReceived_organizationId_reference_key" ON "PaymentReceived"("organizationId","reference"); CREATE INDEX "PaymentReceived_organizationId_paymentDate_idx" ON "PaymentReceived"("organizationId","paymentDate");
CREATE UNIQUE INDEX "CreditNote_organizationId_number_key" ON "CreditNote"("organizationId","number"); CREATE INDEX "CreditNote_organizationId_issueDate_idx" ON "CreditNote"("organizationId","issueDate");
ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PaymentReceived" ADD CONSTRAINT "PaymentReceived_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PaymentReceived" ADD CONSTRAINT "PaymentReceived_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PaymentReceived" ADD CONSTRAINT "PaymentReceived_invoiceId_fkey" FOREIGN KEY("invoiceId") REFERENCES "Invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CreditNote" ADD CONSTRAINT "CreditNote_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CreditNote" ADD CONSTRAINT "CreditNote_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CreditNote" ADD CONSTRAINT "CreditNote_invoiceId_fkey" FOREIGN KEY("invoiceId") REFERENCES "Invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
